short = {t["id"]: t["short_name"] for t in bs["teams"]}


def norm(s):
    return "".join(
        c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c)
    ).lower()


by_name = {}
for e in bs["elements"]:
    by_name.setdefault((norm(e["web_name"]), short[e["team"]]), []).append(e)

