resolved, missing = {}, []
for (name, club), (share, dur, reason) in OVERLAYS.items():
    hits = by_name.get((name, club))
    if not hits:
        missing.append(f"{name} ({club})")
        continue
    if len(hits) > 1:
        missing.append(f"AMBIGUOUS {name} ({club}) -> {len(hits)} matches")
        continue
    e = hits[0]
    resolved[e["id"]] = {
        "start_share": share,
        "duration_gws": dur,
        "reason": reason,
        "_player": f"{e['web_name']} ({club}, {e['now_cost']/10:.1f})",
    }

out = ROOT / "decisions" / "overlays" / "gw01.json"
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(resolved, indent=2, ensure_ascii=False), encoding="utf-8")
print(f"resolved {len(resolved)} overlays -> {out}")
if missing:
    print("UNRESOLVED:")
    for m in missing:
        print("  ", m)
